<?php
require __DIR__.'/../config/app.php';$me=require_role('student');$opportunities=[];$approved=[];$hoursRows=[];$applications=0;$totalHours=0;
try{$q=db()->prepare('SELECT o.id,o.title,o.description,o.event_date,o.venue,a.status FROM volunteer_opportunities o LEFT JOIN volunteer_applications a ON a.opportunity_id=o.id AND a.user_id=? WHERE o.event_date>=? ORDER BY o.event_date,o.title');$q->execute([$me['id'],date('Y-m-d')]);$opportunities=$q->fetchAll();$q=db()->prepare("SELECT o.id,o.title FROM volunteer_opportunities o JOIN volunteer_applications a ON a.opportunity_id=o.id WHERE a.user_id=? AND a.status='Approved' ORDER BY o.event_date");$q->execute([$me['id']]);$approved=$q->fetchAll();$q=db()->prepare('SELECT h.hours,h.notes,h.is_verified,h.recorded_at,o.title FROM volunteer_hours h LEFT JOIN volunteer_opportunities o ON o.id=h.opportunity_id WHERE h.user_id=? ORDER BY h.recorded_at DESC');$q->execute([$me['id']]);$hoursRows=$q->fetchAll();$q=db()->prepare('SELECT COUNT(*) FROM volunteer_applications WHERE user_id=?');$q->execute([$me['id']]);$applications=(int)$q->fetchColumn();$q=db()->prepare('SELECT COALESCE(SUM(hours),0) FROM volunteer_hours WHERE user_id=? AND is_verified=1');$q->execute([$me['id']]);$totalHours=(float)$q->fetchColumn();}catch(Throwable $t){}
$pageTitle='My Volunteering';$activePage='volunteering';$bodyClass='dashboard-page';$sidebarItems=[['Dashboard','student/dashboard.php'],['Explore Events','events.php'],['My Applications','student/applications.php'],['My Volunteering','student/volunteering.php'],['My Cultural Activities','student/cultural-activities.php'],['My Profile','profile.php'],['Notifications','notifications.php'],['Change Password','student/settings.php']];require __DIR__.'/../includes/header.php';
?><div class="dash-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">CAMPUS SERVICE</span><h1>My Volunteering</h1><p>Apply for opportunities, then submit your hours for verification.</p></div></header><div class="admin-summary-grid"><article class="admin-summary-card"><span class="admin-summary-icon teal"><?=eventhub_icon('people')?></span><div><small>Applications</small><strong><?=$applications?></strong></div></article><article class="admin-summary-card"><span class="admin-summary-icon mint"><?=eventhub_icon('chart')?></span><div><small>Verified hours</small><strong><?=number_format($totalHours,1)?></strong></div></article></div><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('people')?></span><div><h2>Volunteer opportunities <span class="admin-count"><?=count($opportunities)?></span></h2><p>Apply to join a campus service activity.</p></div></div><?php if($opportunities):?><div class="student-volunteer-list"><?php foreach($opportunities as $op):?><article class="student-volunteer-card"><span class="student-volunteer-icon"><?=eventhub_icon('star')?></span><div class="student-volunteer-copy"><h3><?=e($op['title'])?></h3><p><?=e($op['description']??'')?></p><small><?=date('d M Y',strtotime($op['event_date']))?> · <?=e($op['venue'])?></small></div><?php if(!$op['status']):?><form method="post" action="<?=url('student/action.php')?>"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="volunteer_apply"><input type="hidden" name="opportunity_id" value="<?=$op['id']?>"><input type="hidden" name="return" value="student/volunteering.php"><button class="btn primary" type="submit">Apply</button></form><?php else:?><span class="pill <?=strtolower(e($op['status']))?>"><?=e($op['status'])?></span><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty">There are no open volunteer opportunities yet.</div><?php endif;?></section><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('chart')?></span><div><h2>Submit volunteer hours</h2><p>Only approved opportunities can receive hour submissions. An admin verifies each entry.</p></div></div><?php if($approved):?><form method="post" action="<?=url('student/action.php')?>" class="form-card admin-event-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="volunteer_hours"><input type="hidden" name="return" value="student/volunteering.php"><div class="admin-form-grid"><label>Opportunity<select name="opportunity_id" required><?php foreach($approved as $op):?><option value="<?=$op['id']?>"><?=e($op['title'])?></option><?php endforeach;?></select></label><label>Hours<input type="number" name="hours" min="0.25" max="24" step="0.25" required></label><label class="admin-form-wide">Notes<textarea name="notes" maxlength="255" rows="2" placeholder="Describe your volunteer work"></textarea></label></div><div class="admin-form-actions"><span class="profile-role">Hours count after verification.</span><button class="btn primary" type="submit">Submit hours</button></div></form><?php else:?><div class="empty">Your volunteer application must be approved before you can submit hours.</div><?php endif;?></section><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('clipboard')?></span><div><h2>My submitted hours <span class="admin-count"><?=count($hoursRows)?></span></h2><p>Track verification progress for your entries.</p></div></div><?php if($hoursRows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Opportunity</th><th>Hours</th><th>Submitted</th><th>Status</th></tr></thead><tbody><?php foreach($hoursRows as $row):?><tr><td><?=e($row['title']??'Volunteer activity')?><?php if($row['notes']):?><small><?=e($row['notes'])?></small><?php endif;?></td><td><?=number_format((float)$row['hours'],1)?></td><td><?=date('d M Y',strtotime($row['recorded_at']))?></td><td><span class="admin-state <?=$row['is_verified']?'published':'draft'?>"><?=$row['is_verified']?'Verified':'Awaiting verification'?></span></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">Your volunteer hour entries will appear here.</div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';
